def sum_of_alternates(test_tuple):
    """Write a function to extract the sum of alternate chains of tuples.

    Returns a 2-tuple whose first element is the sum of the elements
    at odd indices (1, 3, 5, ...) and whose second element is the sum
    of the elements at even indices (0, 2, 4, ...), e.g.
    ``sum_of_alternates((5, 6, 3, 6, 10, 34)) == (46, 18)``.
    """
    return (sum(test_tuple[1::2]), sum(test_tuple[::2]))
